import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第二册：实践与进步 · Lesson 48 Did you want to tell me something?","description":"学习 时间、原因与让步从句，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 48 Did you want to tell me something?","description":"学习 时间、原因与让步从句，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 时间、原因与让步从句，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 47 A thirsty ghost","link":"/life/english/new-concept/book-2/unit-02/lesson-047"},"next":{"text":"第二册：实践与进步 · Lesson 49 The end of a dream","link":"/life/english/new-concept/book-2/unit-03/lesson-049"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 47 A thirsty ghost","link":"/life/english/new-concept/book-2/unit-02/lesson-047"},"next":{"text":"第二册：实践与进步 · Lesson 49 The end of a dream","link":"/life/english/new-concept/book-2/unit-03/lesson-049"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-02/lesson-048.md","filePath":"life/english/new-concept/book-2/unit-02/lesson-048.md"}'),i={name:"life/english/new-concept/book-2/unit-02/lesson-048.md"};function s(l,e,r,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第二册-实践与进步-·-lesson-48-did-you-want-to-tell-me-something" tabindex="-1">第二册：实践与进步 · Lesson 48 Did you want to tell me something? <a class="header-anchor" href="#第二册-实践与进步-·-lesson-48-did-you-want-to-tell-me-something" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 48 Did you want to tell me something?&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>看牙时无法方便说话，点头与简短回应成为交流方式；练习先后动作和时间连接词。本课的语言观察是：as soon as 表一个动作发生后紧接另一个；while 强调同时过程，不能随意替换，否则会把先后变成同时。完成学习后，请写一次不方便说话时的交流，说明非语言回应和随后提出的问题。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>dentist</td><td>/ˈdentɪst/</td><td>n.</td><td>牙医</td><td>visit a dentist</td></tr><tr><td>mouth</td><td>/maʊθ/</td><td>n.</td><td>嘴</td><td>open your mouth</td></tr><tr><td>nod</td><td>/nɒd/</td><td>v.</td><td>点头</td><td>nod politely</td></tr><tr><td>question</td><td>/ˈkwestʃən/</td><td>n.</td><td>问题</td><td>ask a question</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>nod your head — 点头表示回应</li><li>as soon as — 一……就……，突出紧接关系</li></ul><h2 id="语法讲解-时间、原因与让步从句" tabindex="-1">语法讲解：时间、原因与让步从句 <a class="header-anchor" href="#语法讲解-时间、原因与让步从句" aria-label="Permalink to &quot;语法讲解：时间、原因与让步从句&quot;">​</a></h2><p>状语从句为主句提供时间、原因、条件或让步背景。连接词不仅连接形式，也表达逻辑：because 给原因，although 表示让步，while 可以表示同时或对照，until 标记持续的终点。英语通常不把 although 与 but、because 与 so 成对放在同一个复合句中。从句置前时一般用逗号隔开；选连接词前先判断两件事之间的实际关系。本课应用：as soon as 表一个动作发生后紧接另一个；while 强调同时过程，不能随意替换，否则会把先后变成同时。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>As soon as the dentist removed the mirror, I asked a question.</p></blockquote><p>牙医一拿开镜子，我就问了一个问题。</p><p>As soon as 从句给出先发生的动作，主句 asked 紧接其后；两者都是具体过去事件。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>while he removed the mirror 不一定等于拿开之后；表达紧接应使用 as soon as。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>在时间从句后稍停，朗读 asked a question 的连接，不要读成两个独立故事。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>As soon as the dentist removed the mirror, I asked a question. I wanted to know when I could eat. She gave me clear instructions before I left.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写一次不方便说话时的交流，说明非语言回应和随后提出的问题。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：As soon as 从句给出先发生的动作，主句 asked 紧接其后；两者都是具体过去事件。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：while he removed the mirror 不一定等于拿开之后；表达紧接应使用 as soon as。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>选连接词：___ she finished speaking, I replied.（一……就……）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> As soon as</p><p><strong>解析：</strong> 该连接词准确表达紧接发生。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>说话者想知道什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> When they could eat.</p><p><strong>解析：</strong> 示范中的 I 根据转述可用 they 指说话者，重点是进食时间。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>将“我离开前她解释了流程”译成英语。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> She explained the procedure before I left.</p><p><strong>解析：</strong> before 表解释先于离开，不能换成 after。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：时间、原因与让步从句。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-047">上一课</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-03/lesson-049">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const m=t(i,[["render",s]]);export{p as __pageData,m as default};
